use gmp::{Integer, Rational};
use tokio::time::{self, Duration};
use discord::prelude::*;

#[derive(Debug)]
enum Error {
    GmpError(gmp::GmpError),
    IoError(std::io::Error),
}

impl From<gmp::GmpError> for Error {
    fn from(err: gmp::GmpError) -> Error {
        Error::GmpError(err)
    }
}

impl From<std::io::Error> for Error {
    fn from(err: std::io::Error) -> Error {
        Error::IoError(err)
    }
}

#[tokio::main]
async fn main() -> Result<(), Error> {
    // Load the bot token from a file
    let token = std::fs::read_to_string("token.txt")?
        .trim()
        .to_string();

    // Initialize the bot
    let mut client = Client::new(&token)?;

    // Command to calculate the nth Fibonacci number
    client.on_message(|ctx, msg| {
        if msg.content.starts_with("/fib ") {
            let parts: Vec<&str> = msg.content.split_whitespace().collect();
            if parts.len() == 2 {
                if let Ok(n) = parts[1].parse::<u64>() {
                    let fib_number = fibonacci(n);
                    let fib_str = fib_number.to_string();
                    if fib_str.len() > 50 {
                        ctx.say(format!("The {}th Fibonacci number is too big to write. It has {} digits!", n, fib_str.len())).await?;
                    } else {
                        ctx.say(format!("The {}th Fibonacci number is: {} (Computed in {:.4} seconds)", n, fib_number, time::Instant::now().elapsed().as_secs_f64())).await?;
                    }
                }
            }
        }
        if msg.content.starts_with("/isfib ") {
            let parts: Vec<&str> = msg.content.split_whitespace().collect();
            if parts.len() == 2 {
                if let Ok(num) = parts[1].parse::<u64>() {
                    if is_fibonacci(num) {
                        ctx.say(format!("The number {} is in the Fibonacci sequence.", num)).await?;
                    } else {
                        ctx.say(format!("The number {} is not in the Fibonacci sequence.", num)).await?;
                    }
                }
            }
        }
        Ok(())
    });

    // Start the bot
    client.start().await?;

    Ok(())
}

fn fibonacci(n: u64) -> Integer {
    let one = Integer::one();
    let two = Integer::from(2);
    let five = Integer::from(5);

    let sqrt_five = Rational::new(five, one).sqrt();
    let phi = Rational::new(one + &sqrt_five, &two);
    let psi = Rational::new(one - &sqrt_five, &two);

    let phi_pow_n = phi.pow(n as u32);
    let psi_pow_n = psi.pow(n as u32);

    let result = phi_pow_n - &psi_pow_n;
    result / &sqrt_five
}

fn is_fibonacci(num: u64) -> bool {
    let x = num * num * 5 + 4;
    let y = num * num * 5 - 4;
    gmp::is_square(x) || gmp::is_square(y)
}
